<?php
session_start();
if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;}
require_once 'db.php';
$uid=(int)$_SESSION['user_id'];
$cols=array_column($pdo->query('SHOW COLUMNS FROM users')->fetchAll(PDO::FETCH_ASSOC),'Field');
if(!in_array('role',$cols,true)){$pdo->exec("ALTER TABLE users ADD COLUMN role VARCHAR(20) NOT NULL DEFAULT 'user'");$cols[]='role';}
$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$uid]);$current=$q->fetch(PDO::FETCH_ASSOC);
if(!$current){session_destroy();header('Location: login.php');exit;}
$isAdmin=(($current['role']??'')==='admin')||((int)($current['is_admin']??0)===1);
if(empty($_SESSION['admin_users_csrf']))$_SESSION['admin_users_csrf']=bin2hex(random_bytes(32));
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!$isAdmin){http_response_code(403);exit('Звичайний користувач не може змінювати дані інших користувачів.');}
 if(!hash_equals($_SESSION['admin_users_csrf'],(string)($_POST['csrf']??''))){$err='Сесія форми завершилася. Онови сторінку.';}
 else{$target=(int)($_POST['user_id']??0);$role=(string)($_POST['role']??'user');if(!in_array($role,['user','admin'],true))$err='Невідома роль.';elseif($target===$uid && $role!=='admin')$err='Не можна зняти роль адміністратора із самого себе на цій сторінці.';else{$st=$pdo->prepare('UPDATE users SET role=? WHERE id=?');$st->execute([$role,$target]);$msg=$st->rowCount()?'Роль користувача оновлено.':'Змін немає або користувача не знайдено.';}}
}
$cols=array_column($pdo->query('SHOW COLUMNS FROM users')->fetchAll(PDO::FETCH_ASSOC),'Field');
$displayCols=[];foreach(['id','username','name','email','role'] as $c)if(in_array($c,$cols,true))$displayCols[]=$c;
$order=in_array('id',$cols,true)?'id':'username';$users=$pdo->query('SELECT '.implode(',',array_map(fn($c)=>"`$c`",$displayCols)).' FROM users ORDER BY `'.$order.'` ASC')->fetchAll(PDO::FETCH_ASSOC);
function eu($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!DOCTYPE html><html lang="uk"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Користувачі · IT Tasks Pro</title><link rel="stylesheet" href="style.css"><style>
:root{--bg-main:#0b1020;--bg-card:#151f35;--bg-input:#0c1427;--bg-hover:#202d49;--text-main:#edf3ff;--text-muted:#96a6c5;--text-accent:#7c9cff;--border:#293957}*{box-sizing:border-box}body{margin:0;background:var(--bg-main);color:var(--text-main);font-family:Arial,sans-serif}.wrap{max-width:1150px;margin:0 auto;padding:28px 16px}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}.card{background:var(--bg-card);border:1px solid var(--border);border-radius:16px;padding:20px;margin-top:20px}.muted{color:var(--text-muted);line-height:1.5}.btn{padding:9px 12px;border:1px solid var(--border);border-radius:9px;background:var(--bg-hover);color:var(--text-main);text-decoration:none;cursor:pointer;font-weight:700}.notice{padding:12px;border-radius:9px;margin-top:14px}.success{background:#173c30;color:#c5ffe3}.error{background:#4b2027;color:#ffdce0}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:560px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--border);font-size:14px}th{color:var(--text-muted)}select{background:var(--bg-input);color:var(--text-main);border:1px solid var(--border);padding:8px;border-radius:8px}.role-admin{color:#b9c8ff;font-weight:800}.role-user{color:var(--text-muted)}.userform{display:flex;gap:8px;align-items:center}.tag{display:inline-block;padding:5px 8px;border-radius:99px;background:var(--bg-hover);color:var(--text-accent);font-size:12px}
</style></head><body><main class="wrap"><header class="top"><div><span class="tag">IT TASKS PRO · USERS</span><h1>Користувачі</h1><p class="muted"><?=$isAdmin?'Адміністрування облікових записів і ролей.':'Перегляд списку користувачів. Змінювати дані може лише адміністратор.'?></p></div><a class="btn" href="index.php">← На головну</a></header>
<?php if($msg):?><div class="notice success"><?=eu($msg)?></div><?php endif;?><?php if($err):?><div class="notice error"><?=eu($err)?></div><?php endif;?>
<section class="card"><h2>Список користувачів</h2><p class="muted"><?=$isAdmin?'Тільки адміністратор може змінювати роль. Видалення облікових записів тут не виконується.':'У тебе доступ лише для перегляду. Поля керування ролями недоступні.'?></p><div class="tablewrap"><table><thead><tr><?php foreach($displayCols as $c):?><th><?=eu(['id'=>'ID','username'=>'Логін','name'=>'Ім’я','email'=>'Email','role'=>'Роль'][$c]??$c)?></th><?php endforeach;?><?php if($isAdmin):?><th>Дія</th><?php endif;?></tr></thead><tbody><?php foreach($users as $u):?><tr><?php foreach($displayCols as $c):?><td><?php if($c==='role'):?><span class="<?=($u[$c]??'user')==='admin'?'role-admin':'role-user'?>"><?=($u[$c]??'user')==='admin'?'Адміністратор':'Користувач'?></span><?php else:?><?=eu($u[$c]??'')?><?php endif;?></td><?php endforeach;?><?php if($isAdmin):?><td><form class="userform" method="post"><input type="hidden" name="csrf" value="<?=eu($_SESSION['admin_users_csrf'])?>"><input type="hidden" name="user_id" value="<?= (int)($u['id']??0) ?>"><select name="role" aria-label="Роль користувача"><option value="user" <?=($u['role']??'user')==='user'?'selected':''?>>Користувач</option><option value="admin" <?=($u['role']??'user')==='admin'?'selected':''?>>Адміністратор</option></select><button class="btn" type="submit">Зберегти</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
